import { Component, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';

const BASE_COUNT = 120;
const SAVE_MS = 400;
const SAVED_MESSAGE_MS = 1000;

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnDestroy {
  liked = false;
  status = '';
  failed = false;
  requestCount = 0;
  serverDown = false;

  private accepted = false;
  private latest = false;
  private saving = false;
  private saveTimer: ReturnType<typeof setTimeout> | undefined;
  private messageTimer: ReturnType<typeof setTimeout> | undefined;

  // The count follows the like, so the two can never disagree.
  get count(): number {
    return BASE_COUNT + (this.liked ? 1 : 0);
  }

  toggleLike(): void {
    this.latest = !this.latest;
    this.liked = this.latest;
    this.failed = false;
    this.status = 'Saving…';
    clearTimeout(this.messageTimer);
    if (!this.saving) this.startSave();
  }

  ngOnDestroy(): void {
    clearTimeout(this.saveTimer);
    clearTimeout(this.messageTimer);
  }

  private saveLike(value: boolean): Promise<boolean> {
    return new Promise((resolve, reject) => {
      this.saveTimer = setTimeout(() => {
        if (this.serverDown) reject(new Error('Server down'));
        else resolve(value);
      }, SAVE_MS);
    });
  }

  private startSave(): void {
    const value = this.latest;
    this.saving = true;
    this.requestCount += 1;

    this.saveLike(value).then(
      () => {
        this.accepted = value;
        if (this.latest !== value) {
          this.startSave();
          return;
        }
        this.saving = false;
        this.status = 'Saved';
        this.messageTimer = setTimeout(() => {
          this.status = '';
        }, SAVED_MESSAGE_MS);
      },
      () => {
        this.saving = false;
        this.latest = this.accepted;
        this.liked = this.accepted;
        this.status = '';
        this.failed = true;
      }
    );
  }
}

